import csv
import json


def answer() -> int:
    # Dawid Majtyka's great-great-grandparent is Przemysław Kurczab.
    # These direct children each have three grandchildren in the tree.
    qualifying_children = {
        ("Liwia", "Maligłówka"),
        ("Alan", "Wocial"),
    }

    balances = {}
    with open("/app/dataset/people_accounts.csv", newline="") as source:
        for person in csv.DictReader(source):
            name = (person["first_name"], person["last_name"])
            if name in qualifying_children:
                balances[name] = int(person["account_balance"])

    assert set(balances) == qualifying_children
    return sum(balances.values())


if __name__ == "__main__":
    with open("/app/answer.json", "w") as output:
        json.dump(answer(), output)
